  "misconception": {
    "pack_id": null,
    "wrong": "Любой риф сам по себе создаёт ловушку, потому что над дном он выступает вверх.",
    "right": "У биостромов первичной высоты нет, и ловушку создаёт наложенная тектоника. Для биогермов малой амплитуды тектоника тоже ведущий фактор.",
    "claims": ["c4", "c1", "c2"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Карта или разрез рифового тела с отметками кровли и контуром локального поднятия над ним.", "claims": [], "hypothesis": true},
      {"text": "Оценка первичной высоты постройки: заметна она или её нет (биостром).", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Вывод: ловушку создала наложенная тектоника, а не высота самого рифа.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Если локального поднятия нет, правило не даёт вывода о ловушке.", "claims": [], "hypothesis": true},
      {"text": "По карте и разрезу низкий биогерм и биостром могут выглядеть похоже. Различие этот абзац не разбирает.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Риф — как уже записанный слой данных. Тектоника — поздний фильтр поверх него, который задаёт нужную выборку.",
    "breaks_where": "Поднятие меняет сами породы: изгибает и разрывает их. Фильтр данных не меняет."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Без этого новичок считает, что риф сам по себе и есть ловушка. Ловушку может создать поздняя тектоника."
  },
